from PIL import Image
from collections import deque

def blobs(path, pred):
    im = Image.open(path)
    w,h = im.size
    px = im.load()
    mask = [[False]*w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            if pred(px[x,y]):
                mask[y][x]=True
    visited=[[False]*w for _ in range(h)]
    out=[]
    for y in range(h):
        for x in range(w):
            if not mask[y][x] or visited[y][x]:
                continue
            q=deque([(y,x)]); visited[y][x]=True; pts=[]
            while q:
                cy,cx=q.popleft(); pts.append((cy,cx))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<h and 0<=nx<w and mask[ny][nx] and not visited[ny][nx]:
                            visited[ny][nx]=True
                            q.append((ny,nx))
            if len(pts)>8:
                out.append((len(pts), round(sum(p[1] for p in pts)/len(pts),1), round(sum(p[0] for p in pts)/len(pts),1)))
    return sorted(out, key=lambda t:(t[2],t[1]))

def yellow(c):
    r,g,b=c
    return r>200 and g>180 and b<120
print("top001", blobs("/home/robot/captures/top_001.png", yellow))
print("top004", blobs("/home/robot/captures/top_004.png", yellow))
